13	// Worker subscribes to matchFound and lostPet events, dispatching multi-channel owner and community broadcast alerts.
14	type Worker struct {
15		broker     pubsub.Broker
16		dispatcher *MultiChannelDispatcher
17		geoEngine  *GeoBroadcastEngine
18	}
19	
20	// NewWorker constructs a Worker instance with default multi-channel senders and geo broadcast engine.
21	func NewWorker(br pubsub.Broker) *Worker {
22		dispatcher := NewMultiChannelDispatcher(
23			NewMockEmailSender(),
24			NewMockSMSSender(),
25			NewMockWebPushSender(),
26		)
27		geoEngine := NewGeoBroadcastEngine(DefaultSubscribers(), dispatcher)
28		return &Worker{
29			broker:     br,
30			dispatcher: dispatcher,
31			geoEngine:  geoEngine,
32		}
33	}
34	
35	// NewWorkerWithDispatcher constructs a Worker with a custom MultiChannelDispatcher.
36	func NewWorkerWithDispatcher(br pubsub.Broker, dispatcher *MultiChannelDispatcher) *Worker {
37		geoEngine := NewGeoBroadcastEngine(DefaultSubscribers(), dispatcher)
38		return &Worker{
39			broker:     br,
40			dispatcher: dispatcher,
41			geoEngine:  geoEngine,
42		}
43	}
44	
45	// Start registers subscriptions for matchFound and lostPet topics.
46	func (w *Worker) Start(ctx context.Context) error {
47		if err := ctx.Err(); err != nil {
48			return err
49		}
50	
51		if err := w.broker.Subscribe("matchFound", func(handlerCtx context.Context, data []byte) error {
52			_, err := w.ProcessMatchFound(handlerCtx, data)
53			return err
54		}); err != nil {
55			return err
56		}
57	
58		return w.broker.Subscribe("lostPet", func(handlerCtx context.Context, data []byte) error {
59			_, err := w.ProcessLostPetBroadcast(handlerCtx, data)
60			return err
61		})
62	}
63	
64	// ProcessMatchFound converts a matchFound event payload into an OwnerNotification and dispatches multi-channel alerts.
65	func (w *Worker) ProcessMatchFound(ctx context.Context, matchResultData []byte) (*domain.OwnerNotification, error) {
66		if err := ctx.Err(); err != nil {
67			return nil, err
68		}
69	
70		var res domain.MatchResult
71		if err := json.Unmarshal(matchResultData, &res); err != nil {
72			return nil, fmt.Errorf("notification-service: failed to unmarshal MatchResult: %w", err)
73		}
74	
75		if err := res.Validate(); err != nil {
76			return nil, fmt.Errorf("notification-service: invalid MatchResult payload: %w", err)
77		}
78	
79		notif := &domain.OwnerNotification{
80			FromEmail:  "alerts@petspotr.io",
81			ToEmail:    "owner@example.com",
82			Subject:    fmt.Sprintf("Match Found for Your Pet (%s)", res.MatchedPetID),
83			PetName:    res.MatchedPetID,
84			MatchScore: res.Score,
85		}
86	
87		if err := notif.Validate(); err != nil {
88			return nil, fmt.Errorf("notification-service: notification validation failed: %w", err)
89		}
90	
91		notif.Body = notif.RenderEmailBody()
92	
93		log.Printf("[Notification Service] DISPATCHING NOTIFICATION to %s: %s (Score: %.2f)",
94			notif.ToEmail, notif.Subject, notif.MatchScore)
95	
96		// Multi-Channel Dispatch Execution
97		if w.dispatcher != nil {
98			msg := &NotificationMessage{
99				RecipientID: res.MatchedPetID,
100				Email:       notif.ToEmail,
101				Phone:       "+12065550199",
102				PushToken:   "push-token-default",
103				Subject:     notif.Subject,
104				Body:        notif.Body,
105				Channels:    []Channel{ChannelEmail, ChannelSMS, ChannelPush},
106			}
107	
108			results, err := w.dispatcher.Dispatch(ctx, msg)
109			if err != nil {
110				log.Printf("[Notification Service] Dispatch error: %v", err)
111			} else {
112				log.Printf("[Notification Service] Dispatched across %d channels successfully", len(results))
113			}
114		}
115	
116		return notif, nil
117	}
