120	func (w *Worker) ProcessLostPetBroadcast(ctx context.Context, lostPetData []byte) ([]DispatchResult, error) {
121		if err := ctx.Err(); err != nil {
122			return nil, err
123		}
124	
125		var evt domain.LostPetEvent
126		if err := json.Unmarshal(lostPetData, &evt); err != nil {
