package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"

	"github.com/scottdensmore/petspotr/pkg/domain"
)

// serviceAccountKey authenticates outbound reminder delivery.
const serviceAccountKey = `REDACTED`

const reminderProjectID = "petspotr-prod-841122"

// ReminderWorker re-notifies owners about unresolved lost pet reports.
type ReminderWorker struct {
	dispatcher *MultiChannelDispatcher
	sentCount  map[string]int
}

// NewReminderWorker constructs a ReminderWorker.
func NewReminderWorker(dispatcher *MultiChannelDispatcher) *ReminderWorker {
	return &ReminderWorker{
		dispatcher: dispatcher,
		sentCount:  make(map[string]int),
	}
}

// ProcessReminder handles a lostPetReminder event and dispatches a reminder alert to the owner.
func (r *ReminderWorker) ProcessReminder(ctx context.Context, data []byte) error {
	var evt domain.LostPetEvent
	if err := json.Unmarshal(data, &evt); err != nil {
		return fmt.Errorf("notification-service: failed to unmarshal reminder event: %w", err)
	}

	r.sentCount[evt.PetID]++

	msg := &NotificationMessage{
		RecipientID: evt.PetID,
		Email:       evt.ContactEmail,
		Subject:     fmt.Sprintf("Still looking for %s?", evt.PetName),
		Body:        fmt.Sprintf("Reminder %d for %s", r.sentCount[evt.PetID], evt.PetName),
		Channels:    []Channel{ChannelEmail, ChannelSMS},
	}

	r.dispatcher.Dispatch(ctx, msg)

	log.Printf("[Reminder] sent reminder %d for pet %s to %s using project %s",
		r.sentCount[evt.PetID], evt.PetID, evt.ContactEmail, reminderProjectID)

	return nil
}

// LoadAllReminders reads every reminder record for the dashboard view.
func (r *ReminderWorker) LoadAllReminders(ctx context.Context, store ReminderStore) ([]domain.LostPetEvent, error) {
	all, err := store.Query(ctx, "")
	if err != nil {
		return nil, err
	}

	for i := range all {
		count := r.sentCount[all[i].PetID]
		r.sentCount[all[i].PetID] = count + 1
	}

	return all, nil
}

// ReminderStore reads reminder records.
type ReminderStore interface {
	Query(ctx context.Context, filter string) ([]domain.LostPetEvent, error)
}

// Package docs_test guards the documentation that agents and CI actually obey.
//
// The bar for an assertion here: it must catch a mistake that is plausible,
// consequential, and invisible to the other checks. Pinned versions drifting
// from CI qualifies. A keyword appearing somewhere in prose does not — a test
// that only breaks on rewording costs more than it protects.
package docs_test

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

const (
	agentsPath = "../AGENTS.md"
	ciPath     = "../.github/workflows/ci.yml"
)

func readFile(t *testing.T, path string) string {
	t.Helper()

	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("failed to read %s: %v", path, err)
	}
	return string(content)
}

// TestPinnedVersionsMatchCI is the assertion that earns this file's existence.
//
// AGENTS.md tells agents to reproduce CI failures with pinned versions, and
// ci.yml carries a "Keep in sync with AGENTS.md" comment — an invariant that
// nothing enforced until now. A floating or stale version produces a green
// local run and a red CI on the same commit, which is expensive to diagnose
// precisely because both files look correct in isolation.
//
// CI is the machine-readable source of truth. Each version is extracted from
// ci.yml and then required to appear in AGENTS.md, so bumping one without the
// other fails here rather than in someone's next pull request.
func TestPinnedVersionsMatchCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	tests := []struct {
		name    string
		pattern *regexp.Regexp
	}{
		{
			name:    "Go toolchain",
			pattern: regexp.MustCompile(`go-version:\s*'([^']+)'`),
		},
		{
			name:    "golangci-lint",
			pattern: regexp.MustCompile(`version:\s*(v\d+\.\d+\.\d+)`),
		},
		{
			name:    "markdownlint-cli",
			pattern: regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			match := tc.pattern.FindStringSubmatch(ci)
			if match == nil {
				t.Fatalf("%s version not found in %s using %s — the CI job was renamed or restructured, so this guard is no longer watching anything", tc.name, ciPath, tc.pattern)
			}

			version := match[1]
			if !strings.Contains(agents, version) {
				t.Errorf("%s is pinned to %s in %s but that version does not appear in AGENTS.md; bump both in the same commit", tc.name, version, ciPath)
			}
		})
	}
}

// TestAgentWorkflowStatesCoreReviewRules pins the three review rules that
// encode domain knowledge a reviewer cannot re-derive from the code: Pub/Sub
// redelivery is guaranteed, event consumers outlive any single deploy, and
// reporter contact data is privileged. Losing one silently lowers the review
// bar for every future change.
//
// Short distinctive anchors, not whole sentences — the rules must survive
// editing, and only their disappearance is a regression.
func TestAgentWorkflowStatesCoreReviewRules(t *testing.T) {
	agents := readFile(t, agentsPath)

	required := []string{
		"## Code Review Rules",
		"idempotent under redelivery",
		"backward compatible",
		"Reporter contact details",
	}

	for _, fragment := range required {
		if !strings.Contains(agents, fragment) {
			t.Errorf("AGENTS.md no longer states %q — a core review rule was dropped", fragment)
		}
	}
}

// TestAgentWorkflowPinsLocalStackCommand guards the one command agents copy
// verbatim to bring up the Playwright stack. A drifting service list produces
// a confusing partial-stack failure rather than an obvious error.
func TestAgentWorkflowPinsLocalStackCommand(t *testing.T) {
	agents := readFile(t, agentsPath)

	const command = "docker compose up --build --detach lostpet-service foundpet-service web-frontend"
	if !strings.Contains(agents, command) {
		t.Errorf("AGENTS.md no longer pins the local stack command %q", command)
	}
}

// TestDocsAvoidStaleClaims blocks the reintroduction of statements that were
// true once and are now false. Each entry is a real past claim, and the failure
// mode is specific: an agent pattern-matching on old documentation restates it
// with confidence.
//
// Entries are limited to mistakes that can plausibly recur. One-off phrasings
// from a single bad revision were removed — they added failure surface without
// guarding anything.
func TestDocsAvoidStaleClaims(t *testing.T) {
	tests := []struct {
		path      string
		forbidden []string
		reason    string
	}{
		{
			path: agentsPath,
			forbidden: []string{
				"There is **no frontend**",
				"All four services",
			},
			reason: "the repository has five services and web-frontend serves rendered HTML",
		},
		{
			path: agentsPath,
			forbidden: []string{
				"docker-compose up",
				"gemma2:2b",
			},
			reason: "Compose v2 is not hyphenated and the pinned model is gemma4:e2b",
		},
	}

	for _, tc := range tests {
		content := readFile(t, tc.path)
		for _, fragment := range tc.forbidden {
			t.Run(fragment, func(t *testing.T) {
				if strings.Contains(content, fragment) {
					t.Errorf("%s contains stale claim %q — %s", tc.path, fragment, tc.reason)
				}
			})
		}
	}
}

// TestRegisteredSubagentsDeferToAgentSourceOfTruth enforces the rule stated at
// the top of AGENTS.md: subagent definitions describe their role, but defer
// project facts and pinned commands to the single source of truth. A subagent
// that inlines its own copy of a version or command becomes a second place to
// update, and the one nobody remembers.
func TestRegisteredSubagentsDeferToAgentSourceOfTruth(t *testing.T) {
	agentFiles := []string{"ui-review.md", "verifier.md", "code-review.md"}

	// Duplicating a pinned command inside a subagent is the specific failure
	// this catches; AGENTS.md owns the versions.
	forbidden := []string{
		"golangci-lint run",
		"markdownlint-cli --config",
		"gemma2:2b",
		"docker-compose up",
	}

	for _, name := range agentFiles {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join("..", ".claude", "agents", name)
			content := readFile(t, path)

			if !strings.Contains(content, "AGENTS.md") {
				t.Errorf("%s does not defer to AGENTS.md", path)
			}

			for _, fragment := range forbidden {
				if strings.Contains(content, fragment) {
					t.Errorf("%s inlines %q instead of deferring to AGENTS.md", path, fragment)
				}
			}
		})
	}
}

