// Package docs_test guards the documentation that agents and CI actually obey.
//
// The bar for an assertion here: it must catch a mistake that is plausible,
// consequential, and invisible to the other checks. Pinned versions drifting
// from CI qualifies. A keyword appearing somewhere in prose does not — a test
// that only breaks on rewording costs more than it protects.
package docs_test

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

const (
	agentsPath = "../AGENTS.md"
	ciPath     = "../.github/workflows/ci.yml"

	// allowMarker exempts a single line from the stale-claim check, so
	// documentation can quote an anti-pattern in order to warn against it.
	allowMarker = "<!-- docs-test: allow -->"
)

func readFile(t *testing.T, path string) string {
	t.Helper()

	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("failed to read %s: %v", path, err)
	}
	return string(content)
}

// versionPin ties one pinned tool version in CI to every place AGENTS.md
// restates it.
type versionPin struct {
	name string

	// ci captures the version from ci.yml. It must be anchored to the tool it
	// describes: a bare `version:` match would silently retarget to whichever
	// step happens to come first.
	ci *regexp.Regexp

	// docs captures the version from AGENTS.md. Every pattern is applied and
	// every match must agree, because a half-updated document — one mention
	// bumped, another missed — is the most likely form of this drift and the
	// one a "contains it somewhere" check cannot see.
	docs []*regexp.Regexp
}

// TestPinnedVersionsMatchCI is the assertion that earns this file's existence.
//
// AGENTS.md tells agents to reproduce CI failures with pinned versions, and
// ci.yml carries "Keep in sync with AGENTS.md" comments — an invariant that
// both files assert and neither enforced. A stale version produces a green
// local run and a red CI on the same commit, which is expensive to diagnose
// precisely because both files look correct in isolation.
//
// CI is the machine-readable source of truth; AGENTS.md must agree with it
// everywhere it speaks.
func TestPinnedVersionsMatchCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	pins := []versionPin{
		{
			name: "Go toolchain",
			// Quoting is optional in YAML; accept either form.
			ci: regexp.MustCompile(`go-version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("Go toolchain — `(\\d+\\.\\d+\\.\\d+)`"),
				regexp.MustCompile(`must report go(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "golangci-lint",
			// Anchored to the action: the version key belongs to whichever
			// step declares golangci-lint-action, not to the first `version:`
			// in the file.
			ci: regexp.MustCompile(`(?s)golangci-lint-action@.*?version:\s*(v\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`golangci-lint@(v\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "markdownlint-cli",
			ci:   regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "OpenTofu",
			ci:   regexp.MustCompile(`tofu_version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("OpenTofu `(\\d+\\.\\d+\\.\\d+)`"),
			},
		},
	}

	for _, pin := range pins {
		t.Run(pin.name, func(t *testing.T) {
			ciMatch := pin.ci.FindStringSubmatch(ci)
			if ciMatch == nil {
				t.Fatalf("could not locate the %s pin in %s.\n"+
					"Pattern: %s\n"+
					"Either the version moved, its quoting changed, or the step was restructured. "+
					"Update this pattern so the guard keeps watching.", pin.name, ciPath, pin.ci)
			}
			want := ciMatch[1]

			var found []string
			for _, pattern := range pin.docs {
				for _, m := range pattern.FindAllStringSubmatch(agents, -1) {
					found = append(found, m[1])
				}
			}

			if len(found) == 0 {
				t.Fatalf("%s is pinned to %s in %s, but AGENTS.md never states it in a recognized form.\n"+
					"Patterns: %s", pin.name, want, ciPath, patternList(pin.docs))
			}

			// Every mention must agree — not merely one of them.
			for i, got := range found {
				if got != want {
					t.Errorf("%s mention %d of %d in AGENTS.md is %s, but %s pins %s; bump every mention in the same commit",
						pin.name, i+1, len(found), got, ciPath, want)
				}
			}
		})
	}
}

func patternList(patterns []*regexp.Regexp) string {
	out := make([]string, 0, len(patterns))
	for _, p := range patterns {
		out = append(out, p.String())
	}
	return strings.Join(out, ", ")
}

// TestLocalStackCommandMatchesCI checks both sides of the Compose command.
// Asserting only that AGENTS.md contains it would let CI's service list change
// while the documented command rots — the exact drift this file exists to
// catch.
func TestLocalStackCommandMatchesCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	pattern := regexp.MustCompile(`(docker compose up --build --detach [^\n]*)`)
	match := pattern.FindStringSubmatch(ci)
	if match == nil {
		t.Fatalf("could not locate the Compose stack command in %s; update this pattern if the job changed", ciPath)
	}

	command := strings.TrimSpace(match[1])
	if !strings.Contains(agents, command) {
		t.Errorf("CI brings the stack up with %q but AGENTS.md does not document that exact command; agents copy it verbatim", command)
	}
}

// TestAgentWorkflowStatesCoreReviewRules pins the three review rules that
// encode domain knowledge a reviewer cannot re-derive from the code: Pub/Sub
// redelivery is guaranteed, event consumers outlive any single deploy, and
// reporter contact data is privileged. Losing one silently lowers the review
// bar for every future change.
//
// Short distinctive anchors, not whole sentences — the rules must survive
// editing, and only their disappearance is a regression.
func TestAgentWorkflowStatesCoreReviewRules(t *testing.T) {
	agents := readFile(t, agentsPath)

	required := []string{
		"## Code Review Rules",
		"idempotent under redelivery",
		"backward compatible",
		"Reporter contact details",
	}

	for _, fragment := range required {
		if !strings.Contains(agents, fragment) {
			t.Errorf("AGENTS.md no longer states %q — a core review rule was dropped", fragment)
		}
	}
}

// TestDocsAvoidStaleClaims blocks the reintroduction of statements that were
// true once and are now false. Each entry is a real past claim, and the failure
// mode is specific: an agent pattern-matching on old documentation restates it
// with confidence.
//
// The check is line-based so that a line carrying allowMarker can quote an
// anti-pattern deliberately — "use `docker compose up`, not `docker-compose
// up`" is correct documentation and must not fail the build.
func TestDocsAvoidStaleClaims(t *testing.T) {
	staleClaims := []struct {
		fragment string
		reason   string
	}{
		{"There is **no frontend**", "web-frontend serves rendered HTML"},
		{"All four services", "the repository has five services"},
		{"docker-compose up", "Compose v2 is not hyphenated"},
		{"gemma2:2b", "the pinned model is gemma4:e2b"},
	}

	content := readFile(t, agentsPath)
	lines := strings.Split(content, "\n")

	for _, claim := range staleClaims {
		t.Run(claim.fragment, func(t *testing.T) {
			for i, line := range lines {
				if !strings.Contains(line, claim.fragment) {
					continue
				}
				if strings.Contains(line, allowMarker) {
					continue
				}
				t.Errorf("%s:%d contains stale claim %q — %s.\n"+
					"If the line quotes it deliberately, append %s",
					agentsPath, i+1, claim.fragment, claim.reason, allowMarker)
			}
		})
	}
}

// TestRegisteredSubagentsDeferToAgentSourceOfTruth enforces the rule stated at
// the top of AGENTS.md: subagent definitions describe their role, but defer
// project facts and pinned commands to the single source of truth. A subagent
// that inlines its own copy of a version or command becomes a second place to
// update, and the one nobody remembers.
func TestRegisteredSubagentsDeferToAgentSourceOfTruth(t *testing.T) {
	agentFiles := []string{"ui-review.md", "verifier.md", "code-review.md"}

	// Patterns, not literals: the real commands carry version pins
	// (`golangci-lint@v2.12.2 run`), so a bare-string check would never fire
	// on the copy-paste it is meant to catch.
	forbidden := []*regexp.Regexp{
		regexp.MustCompile(`golangci-lint(@v[\d.]+)?\s+run`),
		regexp.MustCompile(`markdownlint-cli(@[\d.]+)?\s+--config`),
		regexp.MustCompile(`docker-compose up`),
		regexp.MustCompile(`gemma\d+:\w+`),
	}

	for _, name := range agentFiles {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join("..", ".claude", "agents", name)
			content := readFile(t, path)

			if !strings.Contains(content, "AGENTS.md") {
				t.Errorf("%s does not defer to AGENTS.md", path)
			}

			for _, pattern := range forbidden {
				if match := pattern.FindString(content); match != "" {
					t.Errorf("%s inlines %q instead of deferring to AGENTS.md; %s",
						path, match, fmt.Sprintf("remove it and cite AGENTS.md, which owns the pinned versions"))
				}
			}
		})
	}
}

