// consequential, and invisible to the other checks. Pinned versions drifting
// from CI qualifies. A keyword appearing somewhere in prose does not — a test
// that only breaks on rewording costs more than it protects.
//
// Guards must fail CLOSED. A guard that quietly stops watching its target is
// worse than no guard, because the green run is read as evidence. Where a
// pattern can lose its anchor, this file fails the test rather than widening
// the search.
package docs_test

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

const (
	agentsPath = "../AGENTS.md"
	ciPath     = "../.github/workflows/ci.yml"

	// allowPrefix exempts a single stale claim on a single line, so
	// documentation can quote an anti-pattern in order to warn against it.
	// The claim must be named — a blanket marker would silence every other
	// claim on the same line.
	//
	//	use `docker compose up`, never `docker-compose up`.
	//	<!-- docs-test: allow: docker-compose up -->
	allowPrefix = "<!-- docs-test: allow: "
)

// stepBoundary splits ci.yml into step blocks. Scoping a lookup to one block
// is what keeps a version pattern from binding to an unrelated key elsewhere
// in the file: Go's RE2 has no lookahead, so a `.*?` gap cannot be bounded
// inside the pattern itself.
var stepBoundary = regexp.MustCompile(`(?m)^\s*- (?:name|uses):`)

func readFile(t *testing.T, path string) string {
	t.Helper()

	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("failed to read %s: %v", path, err)
	}
	return string(content)
}

// ciStep returns the single ci.yml step block containing marker.
func ciStep(t *testing.T, ci, marker string) string {
	t.Helper()

	for _, block := range stepBoundary.Split(ci, -1) {
		if strings.Contains(block, marker) {
			return block
		}
	}

	t.Fatalf("no step in %s references %q — the job was renamed or removed, so this guard is no longer watching anything", ciPath, marker)
	return ""
}

// versionPin ties one pinned tool version in CI to every place AGENTS.md
// restates it.
type versionPin struct {
	name string

	// step, when set, scopes the CI lookup to the step block referencing this
	// marker. Without it, a key as generic as `version:` binds to whichever
	// step happens to match first.
	step string

	// ci captures the version from ci.yml, within step when one is given.
	ci *regexp.Regexp

	// docs captures the version from AGENTS.md. Every pattern is applied and
	// every match must agree, because a half-updated document — one mention
	// bumped, another missed — is the most likely form of this drift and the
	// one a "contains it somewhere" check cannot see.
	//
	// Only mentions in these forms are checked. A version stated in prose the
	// patterns do not recognize is invisible here.
	docs []*regexp.Regexp
}

// TestPinnedVersionsMatchCI is the assertion that earns this file's existence.
//
// AGENTS.md tells agents to reproduce CI failures with pinned versions, and
// ci.yml carries "Keep in sync with AGENTS.md" comments — an invariant that
// both files assert and neither enforced. A stale version produces a green
// local run and a red CI on the same commit, which is expensive to diagnose
// precisely because both files look correct in isolation.
//
// CI is the machine-readable source of truth; AGENTS.md must agree with it
// everywhere it speaks.
func TestPinnedVersionsMatchCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	pins := []versionPin{
		{
			name: "Go toolchain",
			step: "actions/setup-go",
			// Quoting is optional in YAML; accept either form.
			ci: regexp.MustCompile(`go-version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("Go toolchain — `(\\d+\\.\\d+\\.\\d+)`"),
				regexp.MustCompile(`must report go(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "golangci-lint",
			step: "golangci-lint-action",
			ci:   regexp.MustCompile(`version:\s*(v\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`golangci-lint@(v\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "markdownlint-cli",
			ci:   regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "OpenTofu",
			ci:   regexp.MustCompile(`tofu_version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("OpenTofu `(\\d+\\.\\d+\\.\\d+)`"),
			},
		},
	}

	for _, pin := range pins {
		t.Run(pin.name, func(t *testing.T) {
			haystack := ci
			if pin.step != "" {
				haystack = ciStep(t, ci, pin.step)
			}

			ciMatch := pin.ci.FindStringSubmatch(haystack)
			if ciMatch == nil {
				t.Fatalf("could not locate the %s pin in %s.\nPattern: %s\n"+
					"The version key was removed, renamed, or moved out of its step. "+
					"Update this pattern so the guard keeps watching rather than binding to an unrelated key.",
					pin.name, ciPath, pin.ci)
			}
			want := ciMatch[1]

			var found []string
			for _, pattern := range pin.docs {
				for _, m := range pattern.FindAllStringSubmatch(agents, -1) {
					found = append(found, m[1])
				}
			}

			if len(found) == 0 {
				t.Fatalf("%s is pinned to %s in %s, but AGENTS.md never states it in a recognized form.\nPatterns: %s",
					pin.name, want, ciPath, patternList(pin.docs))
			}

			// Every mention must agree — not merely one of them.
			for i, got := range found {
				if got != want {
					t.Errorf("%s mention %d of %d in AGENTS.md is %s, but %s pins %s; bump every mention in the same commit",
						pin.name, i+1, len(found), got, ciPath, want)
				}
			}
		})
	}
}

func patternList(patterns []*regexp.Regexp) string {
	out := make([]string, 0, len(patterns))
	for _, p := range patterns {
		out = append(out, p.String())
	}
	return strings.Join(out, ", ")
}

// TestLocalStackCommandMatchesCI checks both sides of the Compose command, and
// every occurrence on each side. Comparing only the first would let a second,
// stale copy sit further down either file — the same half-update failure the
// version guard exists to catch.
func TestLocalStackCommandMatchesCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	// Exact equality, not containment: a truncated service list is a prefix of
	// the full one and would otherwise pass.
	pattern := regexp.MustCompile(`docker compose up --build --detach[^\n]*`)

	ciCommands := pattern.FindAllString(ci, -1)
	if len(ciCommands) == 0 {
		t.Fatalf("could not locate the Compose stack command in %s; update this pattern if the job changed", ciPath)
	}

	docCommands := pattern.FindAllString(agents, -1)
	if len(docCommands) == 0 {
		t.Fatalf("could not locate the Compose stack command in AGENTS.md; agents copy it verbatim, so it must be documented")
	}

	want := strings.TrimSpace(ciCommands[0])
	for i, got := range append(ciCommands, docCommands...) {
		if strings.TrimSpace(got) != want {
			t.Errorf("Compose stack command occurrence %d disagrees.\n  want: %s\n  got:  %s\n"+
				"CI and AGENTS.md must document the same service list, everywhere both state it",
				i+1, want, strings.TrimSpace(got))
		}
	}
}

// TestAgentWorkflowStatesCoreFacts pins the claims a reviewer or verifier
// cannot re-derive from the code: the three review rules, and the two
// statements about what the test suites actually cover.
//
// Short distinctive anchors, not whole sentences — the text must survive
// editing, and only its disappearance is a regression.
func TestAgentWorkflowStatesCoreFacts(t *testing.T) {
	agents := readFile(t, agentsPath)

	required := []struct {
		fragment string
		guards   string
	}{
		{"## Code Review Rules", "the review rules section itself"},
		{"idempotent under redelivery", "Pub/Sub redelivery is guaranteed, not hypothetical"},
		{"backward compatible", "event consumers outlive any single deploy"},
		{"Reporter contact details", "reporter contact data is privileged"},
		{"in-process cascade", "what the e2e suite actually covers"},
		{"live Ollama", "no suite exercises a live model, so agents must not claim that coverage"},
	}

	for _, req := range required {
		if !strings.Contains(agents, req.fragment) {
			t.Errorf("AGENTS.md no longer states %q — this guarded %s", req.fragment, req.guards)
		}
	}
}

// TestDocsAvoidStaleClaims blocks the reintroduction of statements that were
// true once and are now false. Each entry is a real past claim, and the failure
// mode is specific: an agent pattern-matching on old documentation restates it
// with confidence.
//
// The check is line-based, so a line may exempt one named claim with
// allowPrefix in order to quote it deliberately.
//
// Known limits, both pre-existing: AGENTS.md hard-wraps near 79 columns, so a
// claim split across two lines evades the check, and matching is
// case-sensitive.
func TestDocsAvoidStaleClaims(t *testing.T) {
	staleClaims := []struct {
		fragment string
		reason   string
	}{
		{"There is **no frontend**", "web-frontend serves rendered HTML"},
		{"All four services", "the repository has five services"},
		{"docker-compose up", "Compose v2 is not hyphenated"},
		{"gemma2:2b", "the pinned model is gemma4:e2b"},
		{"CI does **not** run", "CI does run the e2e suite via go test -race ./..."},
		{"Both need the full stack", "the e2e suite is self-contained and needs no stack"},
		{"no local stack for", "the e2e suite is self-contained and needs no stack"},
	}

	content := readFile(t, agentsPath)
	lines := strings.Split(content, "\n")

	for _, claim := range staleClaims {
		t.Run(claim.fragment, func(t *testing.T) {
			exemption := allowPrefix + claim.fragment
			for i, line := range lines {
				if !strings.Contains(line, claim.fragment) {
					continue
				}
				if strings.Contains(line, exemption) {
					continue
				}
				t.Errorf("%s:%d contains stale claim %q — %s.\n"+
					"If the line quotes it deliberately, append %s -->",
					agentsPath, i+1, claim.fragment, claim.reason, exemption)
			}
		})
	}
}

// TestRegisteredSubagentsDeferToAgentSourceOfTruth enforces the rule stated at
// the top of AGENTS.md: subagent definitions describe their role, but defer
// project facts and pinned commands to the single source of truth. A subagent
// that inlines its own copy of a version or command becomes a second place to
// update, and the one nobody remembers.
func TestRegisteredSubagentsDeferToAgentSourceOfTruth(t *testing.T) {
	agentFiles := []string{"ui-review.md", "verifier.md", "code-review.md"}

	// Patterns, not literals: the real commands carry version pins
	// (`golangci-lint@v2.12.2 run`), so a bare-string check would never fire
	// on the copy-paste it is meant to catch. A bare semantic version is
	// included because restating "Go 1.26.5" is the same duplication as
	// restating the command.
	forbidden := []*regexp.Regexp{
		regexp.MustCompile(`golangci-lint(@v[\d.]+)?\s+run`),
		regexp.MustCompile(`markdownlint-cli(@[\d.]+)?\s+--config`),
		regexp.MustCompile(`docker compose up --build`),
		regexp.MustCompile(`docker-compose up`),
		regexp.MustCompile(`gemma\d+:\w+`),
		regexp.MustCompile(`tofu (fmt|validate)`),
		regexp.MustCompile(`go test -race`),
		regexp.MustCompile(`\bv?\d+\.\d+\.\d+\b`),
	}

	for _, name := range agentFiles {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join("..", ".claude", "agents", name)
			content := readFile(t, path)

			// Require a reference, not a substring that merely ends in it.
			if !regexp.MustCompile(`\bAGENTS\.md`).MatchString(content) {
				t.Errorf("%s does not defer to AGENTS.md", path)
			}

			for _, pattern := range forbidden {
				if match := pattern.FindString(content); match != "" {
					t.Errorf("%s inlines %q instead of deferring to AGENTS.md, which owns the pinned versions and commands", path, match)
				}
			}
		})
	}
}

