input.content:
// Package docs_test guards the parts of AGENTS.md that CI also encodes.
//
// Scope is deliberately narrow: every assertion here compares a machine-
// readable value in AGENTS.md against the same value in the CI workflow.
// Version pins, the Compose service list, and the markdownlint file list all
// qualify — they are duplicated verbatim in two files, drift silently, and
// produce a green local run against a red CI on the same commit.
//
// Assertions about prose were removed deliberately. Matching English phrases
// could not distinguish a rule from its negation: a guard on "must remain
// idempotent under redelivery" still passed when the text was changed to "may
// be non-idempotent under redelivery". A guard that survives the inversion of
// the claim it protects is worse than no guard, because the green run reads as
// evidence.
//
// Guards must fail CLOSED. When a pattern stops matching its target, the test
// fails rather than falling back to a broader search — otherwise the guard
// quietly stops watching and still reports green.
package docs_test

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

const (
	agentsPath = "../AGENTS.md"
	ciPath     = "../.github/workflows/ci.yml"
)

// stepBoundary splits ci.yml into step blocks. Scoping every lookup to one
// block is what stops a generic key like `version:` from binding to an
// unrelated step: Go's RE2 has no lookahead, so a `.*?` gap cannot be bounded
// inside the pattern itself.
var stepBoundary = regexp.MustCompile(`(?m)^\s*- (?:name|uses):`)

func readFile(t *testing.T, path string) string {
	t.Helper()

	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("failed to read %s: %v", path, err)
	}
	return string(content)
}

// ciStep returns the one ci.yml step block containing marker, and fails if the
// marker is missing or ambiguous. Returning the first of several matches would
// let a stray mention in an earlier step shadow the real one.
func ciStep(t *testing.T, ci, marker string) string {
	t.Helper()

	var matched []string
	for _, block := range stepBoundary.Split(ci, -1) {
		if strings.Contains(block, marker) {
			matched = append(matched, block)
		}
	}

	switch len(matched) {
	case 1:
		return matched[0]
	case 0:
		t.Fatalf("no step in %s references %q — the step was renamed or removed, so this guard is no longer watching anything", ciPath, marker)
	default:
		t.Fatalf("%d steps in %s reference %q — the marker is ambiguous and could bind to the wrong step; make it more specific", len(matched), ciPath, marker)
	}
	return ""
}

// versionPin ties one pinned tool version in CI to every place AGENTS.md
// restates it.
type versionPin struct {
	name string

	// step scopes the CI lookup to the block referencing this marker. Every
	// pin sets one; an unscoped whole-file search is how a key that moves or
	// gets commented out silently rebinds to another tool's version.
	step string

	// ci captures the version from within that step.
	ci *regexp.Regexp

	// docs captures the version from AGENTS.md. Each pattern must match at
	// least once and every match must agree: a half-updated document is the
	// most likely form of this drift, and checking only the aggregate would
	// let one pattern lose its anchor while the others keep the test green.
	//
	// Only mentions in these forms are checked. A version stated in prose the
	// patterns do not recognize is invisible here.
	docs []*regexp.Regexp
}

// TestPinnedVersionsMatchCI is the assertion this file exists for.
//
// AGENTS.md tells agents to reproduce CI failures with pinned versions, and
// ci.yml carries "Keep in sync with AGENTS.md" comments on all four pins — an
// invariant both files assert and neither enforced. CI is the machine-readable
// source of truth; AGENTS.md must agree with it everywhere it speaks.
func TestPinnedVersionsMatchCI(t *testing.T) {
	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	pins := []versionPin{
		{
			name: "Go toolchain",
			step: "actions/setup-go",
			// Quoting is optional in YAML; accept either form.
			ci: regexp.MustCompile(`go-version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("Go toolchain — `(\\d+\\.\\d+\\.\\d+)`"),
				regexp.MustCompile(`must report go(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "golangci-lint",
			step: "golangci-lint-action",
			ci:   regexp.MustCompile(`version:\s*(v\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`golangci-lint@(v\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "markdownlint-cli",
			step: "Install & Run Markdown Linter",
			ci:   regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			docs: []*regexp.Regexp{
				regexp.MustCompile(`markdownlint-cli@(\d+\.\d+\.\d+)`),
			},
		},
		{
			name: "OpenTofu",
			step: "opentofu/setup-opentofu",
			ci:   regexp.MustCompile(`tofu_version:\s*['"]?(\d+\.\d+\.\d+)['"]?`),
			docs: []*regexp.Regexp{
				regexp.MustCompile("OpenTofu `(\\d+\\.\\d+\\.\\d+)`"),
			},
		},
	}

	for _, pin := range pins {
		t.Run(pin.name, func(t *testing.T) {
			block := ciStep(t, ci, pin.step)

			ciMatch := pin.ci.FindStringSubmatch(block)
			if ciMatch == nil {
				t.Fatalf("could not locate the %s version inside its CI step.\nPattern: %s\n"+
					"The key was removed or renamed. Update this pattern so the guard keeps watching.",
					pin.name, pin.ci)
			}
			want := ciMatch[1]

			// Per-pattern, not aggregate: each documented mention must still
			// be found, so a rewritten sentence fails loudly instead of
			// leaving that mention unguarded.
			for _, pattern := range pin.docs {
				matches := pattern.FindAllStringSubmatch(agents, -1)
				if len(matches) == 0 {
					t.Errorf("%s is pinned to %s in %s, but AGENTS.md no longer states it in the form %s.\n"+
						"Either restore that wording or update this pattern — as written, that mention is unguarded.",
						pin.name, want, ciPath, pattern)
					continue
				}

				for i, m := range matches {
					if m[1] != want {
						t.Errorf("%s mention %d of %d matching %s is %s, but %s pins %s; bump every mention in the same commit",
							pin.name, i+1, len(matches), pattern, m[1], ciPath, want)
					}
				}
			}
		})
	}
}

// TestLocalStackCommandMatchesCI compares every occurrence on both sides.
// Exact equality, not containment: a truncated service list is a prefix of the
// full one and would otherwise pass.
func TestLocalStackCommandMatchesCI(t *testing.T) {
	assertCommandMatches(t,
		regexp.MustCompile(`docker compose up --build --detach[^\n]*`),
		"Compose stack command",
		"agents copy it verbatim to bring up the Playwright stack",
	)
}

// TestMarkdownlintFileListMatchesCI guards the invariant AGENTS.md names as a
// landmine: "The file list is hardcoded in the workflow; renaming or adding a
// top-level doc requires updating it in the same commit." Adding a doc to one
// list and not the other means the new file is silently unlinted, or the local
// command fails on a file CI does not check.
func TestMarkdownlintFileListMatchesCI(t *testing.T) {
	assertCommandMatches(t,
		regexp.MustCompile(`"AGENTS\.md"[^\n]*`),
		"markdownlint file list",
		"a doc missing from one list is silently unlinted",
	)
}

// assertCommandMatches requires a command to appear identically in AGENTS.md
// and ci.yml, in every place either file states it.
func assertCommandMatches(t *testing.T, pattern *regexp.Regexp, name, why string) {
	t.Helper()

	agents := readFile(t, agentsPath)
	ci := readFile(t, ciPath)

	ciMatches := pattern.FindAllString(ci, -1)
	if len(ciMatches) == 0 {
		t.Fatalf("could not locate the %s in %s using %s; update this pattern if the job changed", name, ciPath, pattern)
	}

	docMatches := pattern.FindAllString(agents, -1)
	if len(docMatches) == 0 {
		t.Fatalf("could not locate the %s in AGENTS.md using %s — %s, so it must be documented", name, pattern, why)
	}

	want := strings.TrimSpace(ciMatches[0])
	for i, got := range append(ciMatches, docMatches...) {
		if strings.TrimSpace(got) != want {
			t.Errorf("%s occurrence %d disagrees.\n  want: %s\n  got:  %s\n%s",
				name, i+1, want, strings.TrimSpace(got), why)
		}
	}
}

// TestRegisteredSubagentsDeferToAgentSourceOfTruth enforces the rule stated at
// the top of AGENTS.md: subagent definitions describe their role, but defer
// pinned commands and versions to the single source of truth. A subagent that
// inlines its own copy becomes a second place to update, and the one nobody
// remembers.
//
// This is the one guard here that reads the agent definitions rather than CI.
// It is kept because it matches commands and version literals — mechanical
// strings — not prose.
func TestRegisteredSubagentsDeferToAgentSourceOfTruth(t *testing.T) {
	agentFiles := []string{"ui-review.md", "verifier.md", "code-review.md"}

	// Patterns, not literals: the real commands carry version pins
	// (`golangci-lint@v2.12.2 run`), so a bare-string check would never fire
	// on the copy-paste it is meant to catch.
	forbidden := []*regexp.Regexp{
		regexp.MustCompile(`golangci-lint(@v[\d.]+)?\s+run`),
		regexp.MustCompile(`markdownlint-cli(@[\d.]+)?\s+--config`),
		regexp.MustCompile(`docker[ -]compose up`),
		regexp.MustCompile(`tofu (fmt|validate)`),
		regexp.MustCompile(`go test -race`),
		regexp.MustCompile(`npx playwright test`),
		// Bare version literals, including the `go1.26.5` form AGENTS.md tells
		// agents to look for — there is no word boundary between `o` and `1`,
		// so a `\b`-anchored pattern would miss it.
		regexp.MustCompile(`\bgo\d+\.\d+\.\d+`),
		regexp.MustCompile(`\bv?\d+\.\d+\.\d+\b`),
	}

	for _, name := range agentFiles {
		t.Run(name, func(t *testing.T) {
			path := filepath.Join("..", ".claude", "agents", name)
			content := readFile(t, path)

			// A real reference, not a substring that merely ends in it: `\b`
			// would match inside `NOT-AGENTS.md`, since `-` is already a
			// non-word character. RE2 has no lookbehind, so both sides are
			// spelled out.
			if !regexp.MustCompile(`(^|[^\w-])AGENTS\.md($|[^\w])`).MatchString(content) {
				t.Errorf("%s does not defer to AGENTS.md", path)
			}

			for _, pattern := range forbidden {
				if match := pattern.FindString(content); match != "" {
					t.Errorf("%s inlines %q instead of deferring to AGENTS.md, which owns the pinned versions and commands", path, match)
				}
			}
		})
	}
}

