func TestMarkdownlintFileListMatchesCI(t *testing.T) {
	ciFiles := markdownlintFiles(t, readCI(t), ciPath)
	docFiles := markdownlintFiles(t, readFile(t, agentsPath), agentsPath)

	if !slices.Equal(ciFiles, docFiles) {
